from decimal import Decimal, InvalidOperation


def amount(text):
    """Parse a monetary string into an exact Decimal.

    Raises ValueError for non-string input, invalid decimal strings,
    non-finite values, and negative values.
    """
    if not isinstance(text, str):
        raise ValueError("price must be a string")
    try:
        value = Decimal(text)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError("invalid price string: %r" % (text,))
    if not value.is_finite():
        raise ValueError("price must be finite: %r" % (text,))
    if value < 0:
        raise ValueError("price must be nonnegative: %r" % (text,))
    return value

