from decimal import Decimal, ROUND_HALF_UP

from shop.money import amount

_CENT = Decimal("0.01")
_SCALE = Decimal(10000)


def _validate_discount(discount_bps):
    if isinstance(discount_bps, bool) or not isinstance(discount_bps, int):
        raise ValueError("discount_bps must be an integer")
    if discount_bps < 0 or discount_bps > 10000:
        raise ValueError("discount_bps must be in [0, 10000]")
    return discount_bps


def _validate_quantity(quantity):
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        raise ValueError("quantity must be an integer")
    if quantity < 0:
        raise ValueError("quantity must be nonnegative")
    return quantity


def checkout(lines, discount_bps):
    bps = _validate_discount(discount_bps)

    if lines is None:
        raise ValueError("lines must be an iterable of line dictionaries")

    factor = Decimal(10000 - bps) / _SCALE
    total = Decimal(0)
    for line in lines:
        if not isinstance(line, dict):
            raise ValueError("each line must be a dictionary")
        if "price" not in line or "quantity" not in line:
            raise ValueError("line missing required field")
        price = amount(line["price"])
        quantity = _validate_quantity(line["quantity"])
        line_total = price * quantity * factor
        total += line_total.quantize(_CENT, rounding=ROUND_HALF_UP)

    return int(total.scaleb(2).to_integral_value(rounding=ROUND_HALF_UP))
